const supersedeEarlierFailedAssignmentsOnTrack = `-- name: SupersedeEarlierFailedAssignmentsOnTrack :execrows
UPDATE room_assignment AS older
SET superseded_by_assignment_id = $1,
    failure_acknowledged_at = COALESCE(older.failure_acknowledged_at, now()),
    updated_at = now()
WHERE older.room_id = $2
  AND older.source_message_id = $3
  AND older.assignee_id = $4
  AND older.status = 'failed'
  AND older.id <> $1
  AND older.id < $1
  AND older.superseded_by_assignment_id IS NULL
`

type SupersedeEarlierFailedAssignmentsOnTrackParams struct {
	NewAssignmentID pgtype.UUID `json:"new_assignment_id"`
	RoomID          pgtype.UUID `json:"room_id"`
	SourceMessageID pgtype.UUID `json:"source_message_id"`
	AssigneeID      pgtype.UUID `json:"assignee_id"`
}

func (q *Queries) SupersedeEarlierFailedAssignmentsOnTrack(ctx context.Context, arg SupersedeEarlierFailedAssignmentsOnTrackParams) (int64, error) {
	result, err := q.db.Exec(ctx, supersedeEarlierFailedAssignmentsOnTrack,
		arg.NewAssignmentID,
		arg.RoomID,
		arg.SourceMessageID,
		arg.AssigneeID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

